PASSAGES = [
 dict(id="K1", title="カズオ（1）", page="252", lines="1〜6行目", chars=["カズオ"],
  text="カズオは電車の中にいる。ロングシートの席に座って、さっきから{①|胸をドキドキさせて。}\n目の前に、二人のおばあさんが立っている。\n{②|席を譲らなくちゃ——。}でも、カズオが立ち上がっても、シートには一人分のスペースしか空かない。おばあさん二人のうち、座れるのは一人だけだ。"),
 dict(id="K2", title="カズオ（2）", page="252", lines="7〜14行目", chars=["カズオ"],
  text="年をとっているほうのおばあさんに声をかけようか。だけど、若く見えるおばあさんは大きな荷物を持っている。遠くの駅まで乗るほうに座ってもらおうと思っても、行き先なんてわからない。二人で話し合って決めればいい？ {①|そんなの}、どうやってお願いすればいいんだろう……。\nおばあさんたちは、怒っているかもしれない。それとも悲しんでいるのだろうか。カズオは{②|二人と目が合うのが怖くて}、うつむいてしまう。{③|それだけでは足りずに、目もつぶった。}"),
 dict(id="K3", title="カズオ（3）", page="253上段", lines="1〜9行目", chars=["カズオ"],
  text="{①|座れるおばあさんと座れないおばあさんを分けてしまうのはよくないんだ、と自分に言い聞かせた。}そんなの不公平だもの。座れないおばあさんがかわいそうだもの。だったら二人とも座れないほうがすっきりする{②|……はずだ。}\n{③|電車は走る。}ガタゴトと揺れながら、走る。周りの人は、カズオのことを「優しくない子供」だと思っているかもしれない。{④|本当は違うのに。}おばあさんが一人だけなら、すぐに席を譲ってあげたいのに。カズオは胸をドキドキさせたまま、{⑤|ただじっと目をつぶって、眠ったふりをする。}"),
 dict(id="T1", title="タケシ（1）", page="253上段", lines="10〜20行目", chars=["タケシ"],
  text="タケシは電車の中にいる。ロングシートの席に座って、さっきから{①|唇をキュッとかみしめて。}\nどうしてオレの前に立つんだよ。目の前にいるおじいさんに文句を言ってやりたい。\nおじいさんは、タケシが席を譲ってくれるのを待っているように見える。いつまでたってもタケシが立ち上がらないからムッとしているようにも、見える。\n{②|そんなのヤだよ——。}だって、オレもちゃんと切符を買って電車に乗ってるんだから。席に座る権利はある。絶対にある。おじいさんに「席を譲ってくれませんか。」と頼まれたのならともかく、{③|自分からその権利を捨てるなんて、おかしいじゃないか……。}"),
 dict(id="T2", title="タケシ（2）", page="253下段", lines="2〜11行目", chars=["タケシ"],
  text="つり革につかまったおじいさんは、電車が揺れるたびに足をふらつかせて、倒れそうになる。{①|席を譲ってあげたら、きっと喜ぶだろう。}でも、電車の中には他にもたくさん座っている人がいる。小学生のタケシより大きな子供も、若者も、大人も、席に座っている。タケシは、{②|たまたま}、おじいさんの前に座っているだけだ。{③|なにも自分が席を譲らなくても、誰かが立ち上がればいい。}「目の前にいる人が席を譲ること」という法律はないのだし、そもそも「お年寄りには必ず席を譲ること」と決められているわけでもないのだから、タケシが席を立つ必要なんて、どこにもない{④|……はずだ。}"),
 dict(id="T3", title="タケシ（3）", page="253下段", lines="12〜19行目", chars=["タケシ"],
  text="電車は走る。おじいさんは体を危なっかしく揺らしている。周りの人はタケシを{①|ちらちら見る。}「おじいさんを座らせてあげなさい。」と{②|無言で伝えているのだろうか。}だったら、{③|そう思う人}が席を譲ればいいのに。{④|みんな身勝手だ。ひきょうだ。}タケシは唇をかみしめたまま、本を読み始めた。でも、同じ行を何度も読んだり、ページをとばしてめくったことにしばらく気づかなかったりして、{⑤|本の内容はちっとも頭に入ってこなかった。}"),
 dict(id="H1", title="ヒナコ（1）", page="253下段〜254上段", lines="253下20行目〜254上8行目", chars=["ヒナコ"],
  text="ヒナコは電車の中にいる。ロングシートの席に座って、さっきから{①|ため息を何度も飲み込んで。}\n赤ちゃんを抱っこして、小さなお兄ちゃんも連れたお母さんが、目の前に立っている。（中略）両足をふんばって、なんとか体を支えている。\n席を譲ってあげたい——。{②|いつもなら、ためらうことなく立ち上がって}、「ここ、どうぞ。」と声をかけているはずだ。\n{③|でも、今日はダメ。悪いけど、今日はダメ。ごめんなさい。}"),
 dict(id="H2", title="ヒナコ（2）", page="254上段", lines="9〜16行目", chars=["ヒナコ"],
  text="頭が痛い。ちょっと気分も悪い。乗り物酔いをしてしまったようだし、背中がゾクゾクして寒けもするから、もしかしたら風邪をひきかけているのかもしれない。{①|こんな体調で席を譲ったら、こっちが倒れてしまう。}\n{②|お願い、許してください、と心の中で謝った。}周りの人には頭痛も寒けもわからない。だから、私のことを「なんてひどい子供なんだ。」と思っているかもしれない、と想像するだけで、{③|ヒナコは泣きそうになってしまう。}"),
 dict(id="H3", title="ヒナコ（3）", page="254上段〜下段", lines="254上17行目〜下段", chars=["ヒナコ"],
  text="隣の席のおじさんが「どうぞ。」とお母さんに席を譲った。お母さんはホッとした様子で「ありがとうございます。」とお礼を言って座った。よかった。{①|ヒナコまでホッとした。}\nでも、お母さんと入れ替わりにヒナコの目の前に立ったおじさんは、{②|小さく舌打ちをした。}\n{③|怒ってる——？ 私のことを——？}\n違うのに。私は席を{④|「譲らなかった」のではなく、「譲りたくても譲れなかった」}のに。お願い、わかってください。"),
 dict(id="H4", title="ヒナコ（4）", page="254下段", lines="", chars=["ヒナコ"],
  text="ノートに『私はぐあいが悪いんです。』と書いて、{①|看板みたいに}持っていようか。そうすればみんなもわかってくれる。\nだけど、{②|それもうそだと思われたら……どうしよう……。}\n電車は走る。{③|ヒナコの降りる駅はまだずっと先だったが、次の駅で降りよう、と決めた。}ホームのベンチに座って少し休もう。{④|この電車には、もう乗っていたくない。}ヒナコはうつむいた。まぶたが急に熱くなって、{⑤|涙がぽとんと膝に落ちた。}"),
 dict(id="S1", title="サユリ（1）", page="254下段", lines="", chars=["サユリ"],
  text="サユリは電車の中にいる。ロングシートの席に座って、さっきから{①|ワクワクした胸の高鳴りを抑えて。}\n目の前に、松葉づえをついたお姉さんが立っている。骨折したのだろう、左足に真新しいギプスをつけて、松葉づえを何度も握り直して、揺れる電車の中で立っているのは大変そうだ。\n席を譲ろう——。{②|生まれて初めてのことだ。}両親や学校の先生に教わった「助け合いの心」を発揮するチャンスを、ずっと待っていた。{③|ついに、やっと、そのときが訪れたのだ。}"),
 dict(id="S2", title="サユリ（2）", page="254下段〜255上段", lines="", chars=["サユリ"],
  text="「あの……ここ、どうぞ！」\n立ち上がって、お姉さんに声をかけた。{①|やった。うまく言えた。にっこり笑うこともできた。}\nお姉さんは小さく会釈をして、座った。\n{②|それだけ——？}\n会釈のときに低い声でぼそっと「あ、どーも。」と言ったきり、お礼の言葉も感激の笑顔もない。{③|せっかく勇気を出して譲ってあげたのに}、まるでそんなの当然のことだとでも言うように……（中略）とにかくお姉さんはめんどうくさそうに座って、イヤホンで音楽を聴き始めたのだ。\nがっかりした。{④|感謝してくれないんだったら席を譲らなきゃよかった、と思った。}"),
 dict(id="S3", title="サユリ（3）", page="255上段〜256上段", lines="", chars=["サユリ"],
  text="あーあ、とつり革につかまっていたら、隣に立っていたおばさんが「えらいわねえ。」と、にこにこ笑いながら褒めてくれた。{①|よかった。ちゃんとわかってくれる人がいた。}周りの人もこっちを見ている。{②|サユリは胸を張って言った。}\n「だって、{③|困ってる人やかわいそうな人を助けてあげるのは当然のことです！}」\nおばさんは「そうね、そのとおりね。」と——言ってくれなかった。にこにこ笑っていた顔が{④|一瞬こわばったように見えた。}{⑤|周りの人たちが目をそらしている}ことにも気づいた。"),
 dict(id="S4", title="サユリ（4）", page="256上段", lines="2〜15行目", chars=["サユリ"],
  text="どうして褒めてもらえなかったのか、サユリにはわからない。ただ、周囲の空気が急にどんよりと重くなって、{①|なんともいえず居心地が悪くなっていた。}\n（中略）「この子にちゃんとお礼を言いなさいよ。」とおばさんが言ってくれればいいのに。周りの人も、{②|恩知らずのお姉さん}を冷たい目で見てくれればいいのに。でも、なんだか逆に、{③|サユリのほうがみんなに叱られているような気がしてしかたない。}\nなんで？ ねえ、なんで——？\n電車は走る。{④|サユリはつり革を強く握りしめる。}何がなんだかわからないまま、{⑤|さっきのひと言をお姉さんに聞かれなくてよかったのかもしれない}と、ふと思った。なぜそう思ったのかも、わからないまま、だったけれど。"),
 dict(id="E1", title="結び（僕たち）", page="256上段〜257上段", lines="256上16行目〜257上9行目", chars=["語り手"],
  text="{①|僕たちは、みんな、電車の中にいる。}「世の中」という名前の電車に乗り合わせた乗客だ、僕たちは誰もが。\n座っている人もいる。立っている人もいる。重い荷物を提げた人もいれば、身軽な人もいる。{②|「私の正しさ」は、乗っている人の数だけある。}でも、それは必ずしも「他の人の正しさ」とは一致しない。なんとなく決まっている「みんなの正しさ」（{③|それ}を「常識」と呼ぶ）から、「それぞれの正しさ」がはみ出してしまうことだって、ある。\n電車は走る。数えきれない「正しさ」は、すれ違ったりぶつかり合ったりしながら、電車に揺られている。{④|床に転がって誰かに踏みつぶされてしまった「正しさ」}も、きっとそこにはあるだろう。{⑤|あなたの「正しさ」はどこにある？}（後略）"),
]
